-- Phase 1 hardening. Original 20261114120000 is preserved: hosted application state is unknown.
-- Generated by Supabase CLI migration new; version advanced past the future-dated dependency.
-- No historical rows are rewritten or discarded. If Phase 1 has received data, stop and get
-- Owner review of a separate data-preserving upgrade before applying this migration.
begin;
lock table reservation_private.inbox, reservation_private.reservations,
  reservation_private.reservation_table_links, reservation_private.reservation_events in access exclusive mode;
do $$ begin
  if exists(select 1 from reservation_private.inbox)
     or exists(select 1 from reservation_private.reservations)
     or exists(select 1 from reservation_private.reservation_table_links)
     or exists(select 1 from reservation_private.reservation_events) then
    raise exception 'reservation_phase1_data_requires_owner_review' using errcode = '55000';
  end if;
end $$;

